/************************************************
 * PRODUCTION ANTI-JOIN AGAINST PAYMENT_STATUS
 * - Primary Key: voucher_no
 * - Fallback: party + date + amount
 * - Logs duplicates safely
 ************************************************/

/**
 * INPUTS
 */
const incomingItems = $input.all();

const paymentNodeItems = (() => {
  try {
    return $items("Payment_Status") || [];
  } catch (e) {
    return [];
  }
})();

const existingItems = paymentNodeItems.map(i => i.json);

/************************************************
 * HELPERS
 ************************************************/

const norm = v => String(v || "").trim().toLowerCase();

const parseDate = v => {
  if (!v) return "";

  if (typeof v === "number") {
    const d = new Date((v - 25569) * 86400 * 1000);
    return isNaN(d) ? "" : d.toISOString().slice(0, 10);
  }

  const d = new Date(v);
  if (!isNaN(d)) return d.toISOString().slice(0, 10);

  const m = String(v).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2]}-${m[1]}`;

  return "";
};

const amountToCents = v => {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  if (isNaN(n)) return null;
  return Math.round(n * 100);
};

/************************************************
 * STEP 1️⃣ BUILD LOOKUP SETS
 ************************************************/

const existingVoucherSet = new Set();
const existingFallbackSet = new Set();

for (const r of existingItems) {

  const voucher = norm(r["Voucher No"]);
  const party   = norm(r["Party Name"]);
  const date    = parseDate(r["Order Date"]);
  const bill    = amountToCents(r["Bill Amount"]);

  if (voucher) {
    existingVoucherSet.add(voucher);
  }

  if (party && date && bill !== null) {
    existingFallbackSet.add(`${party}|${date}|${bill}`);
  }
}

/************************************************
 * STEP 2️⃣ FILTER + VALIDATE + DEDUPE
 ************************************************/

const output = [];
const seenIncomingVoucher = new Set();
const seenIncomingFallback = new Set();

for (const item of incomingItems) {

  const r = item.json;

  if (
    !r ||
    typeof r !== "object" ||
    !("party_name" in r) ||
    !("order_date" in r) ||
    !("bill_amount" in r)
  ) {
    continue;
  }

  const voucher = norm(r.voucher_no);
  const party   = norm(r.party_name);
  const date    = parseDate(r.order_date);
  const bill    = amountToCents(r.bill_amount);

  if (!party || !date || bill === null) continue;

  const fallbackKey = `${party}|${date}|${bill}`;

  /************************************************
   * PRIMARY MATCH → voucher_no
   ************************************************/
  if (voucher) {

    if (existingVoucherSet.has(voucher)) {
      console.log(`Skipped existing voucher: ${voucher}`);
      continue;
    }

    if (seenIncomingVoucher.has(voucher)) {
      console.log(`Duplicate in batch voucher: ${voucher}`);
      continue;
    }

    seenIncomingVoucher.add(voucher);
  }

  /************************************************
   * FALLBACK MATCH → party+date+amount
   ************************************************/
  else {

    if (existingFallbackSet.has(fallbackKey)) {
      console.log(`Skipped existing fallback: ${fallbackKey}`);
      continue;
    }

    if (seenIncomingFallback.has(fallbackKey)) {
      console.log(`Duplicate in batch fallback: ${fallbackKey}`);
      continue;
    }

    seenIncomingFallback.add(fallbackKey);
  }

  output.push({ json: r });
}

/************************************************
 * STEP 3️⃣ SAFE FIFO SORT
 ************************************************/

output.sort((a, b) => {

  const da = parseDate(a.json.order_date);
  const db = parseDate(b.json.order_date);

  if (da && db && da !== db) return da.localeCompare(db);
  if (da && !db) return -1;
  if (!da && db) return 1;

  return norm(a.json.party_name)
    .localeCompare(norm(b.json.party_name));
});

/************************************************
 * FINAL OUTPUT
 ************************************************/

console.log(`Incoming: ${incomingItems.length}`);
console.log(`Existing: ${existingItems.length}`);
console.log(`Output (new records): ${output.length}`);

return output;

const output = [];

for (const item of items) {
  const d = item.json;

  const excelDate = d["Mittal Corporation"] || d["Mittal Enterprises"];
  const party = d["__EMPTY"];
  const vchType = d["__EMPTY_1"];
  const vchNo = d["__EMPTY_2"];
  const debit = d["__EMPTY_3"] || 0;
  const credit = d["__EMPTY_4"] || 0;

  // Skip junk rows
  if (!party || typeof excelDate !== "number") continue;

  // We only want Sales (Tax Invoice) and Receipts
  if (!["Sales", "Receipt","Credit Note (Sale)"].includes(vchType)) continue;

  // Convert Excel date
  const orderDate = new Date((excelDate - 25569) * 86400 * 1000)
    .toISOString()
    .split("T")[0];

  output.push({
    order_date: orderDate,
    party_name: party,
    voucher_type: vchType,
    voucher_no: vchNo || null,
    bill_amount: vchType === "Sales" ? debit : null,
    payment_received: vchType === "Receipt" ||vchType === "Credit Note (Sale)"  ? credit : null,
    payment_mode: vchType === "Receipt" ? d["__EMPTY_2"] : null
  });
}


return output.map(o => ({ json: o }));

